public class UseFlameSlash : ProjectileAttackState
{
	public new static string staticID = "UseFlameSlash";

	private float flyTime = 0.35f;

	private FlameSlash currentFS;

	private Vector2 spawnPosition;

	private Vector2 spawnOffset;

	private Vector2 perpendVec;

	private int ultStopwatchID;

	private int ultCounter;

	private bool ultStarted;

	public override string OnEnterAnimStr => (!IsEmpowered) ? parent.NextHandAnimStr : parent.PBAoEAnimStr;

	public UseFlameSlash(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.25f, 0.2f, 0.3f, 0.6f, 0.75f);
		InitChargeSkillSettings(2, 0.125f, skillData, this);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		flyTime = ((!IsEmpowered) ? 0.35f : 0.45f);
	}

	public override void OnEnter()
	{
		if (isUltimate)
		{
			SetSkillLevel(2);
			cooldownRef.chargeCount = 0;
			ultStarted = false;
		}
		else
		{
			SetSkillLevel(1);
		}
		base.OnEnter();
		spawnOffset = inputVector * 0.5f;
	}

	public override void ExecuteSkill()
	{
		if (isUltimate)
		{
			if (!ultStarted)
			{
				ultStarted = true;
				ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, 6);
				ultCounter = 0;
			}
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				spawnPosition = (Vector2)parent.attackOriginTrans.position + spawnOffset;
				if (ultCounter == 0)
				{
					perpendVec = Globals.GetPerpendicular(inputVector) * 0.5f;
					CreateFlameSlash(spawnPosition + perpendVec, inputVector, flipX: true);
					CreateFlameSlash(spawnPosition - perpendVec, inputVector);
				}
				else
				{
					for (int i = -ultCounter; i <= ultCounter; i++)
					{
						CreateFlameSlash(spawnPosition, Globals.GetRotatedCircleVector(24, i, inputVector));
					}
				}
				ultCounter++;
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
				break;
			}
		}
		else
		{
			base.ExecuteSkill();
			spawnPosition = (Vector2)parent.attackOriginTrans.position + spawnOffset;
			if (IsEmpowered)
			{
				perpendVec = Globals.GetPerpendicular(inputVector) * 0.5f;
				CreateFlameSlash(spawnPosition + perpendVec, inputVector, flipX: true);
				CreateFlameSlash(spawnPosition - perpendVec, inputVector);
			}
			else
			{
				CreateFlameSlash(spawnPosition, inputVector, !parent.forehandAnimPlayed);
			}
		}
	}

	private void CreateFlameSlash(Vector2 givenPosition, Vector2 givenVector, bool flipX = false)
	{
		CameraController.ShakeCamera(0.4f);
		currentFS = (FlameSlash)CreateProjectile(FlameSlash.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector));
		currentFS.flyTime = flyTime;
		if (flipX)
		{
			currentFS.transform.localScale = new Vector3(-1f, 1f, 1f);
		}
		FireProjectile(currentFS, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
	}
}

